<?php defined('ABSPATH')||exit; $product=$args['product']??null; if(!$product instanceof WC_Product)return; $id=$product->get_id(); $title=$product->get_name(); $url=get_permalink($id); $image_id=$product->get_image_id(); $available=$product->is_in_stock()&&$product->is_purchasable(); $can_add=$available&&$product->is_type('simple'); $price=$product->get_price_html(); $terms=get_the_terms($id,'product_cat'); $category=null; if($terms&&!is_wp_error($terms)){ $deepest=-1; foreach($terms as $term){ $depth=count(get_ancestors($term->term_id,'product_cat')); if($depth>$deepest){ $deepest=$depth; $category=$term; } } } $category_url=$category?get_term_link($category):''; $description=trim($product->get_short_description()); if($description==='')$description=trim($product->get_description()); $description=wp_strip_all_tags($description); $ajax_url=$can_add&&class_exists('WC_AJAX') ?WC_AJAX::get_endpoint('add_to_cart') :''; $show_cart=$can_add&&!empty($ajax_url); ?> <article class="bp-product-card"> <a class="bp-product-card__link" href="<?php echo esc_url($url); ?>" aria-label="<?php echo esc_attr('مشاهده '.$title); ?>"> </a> <figure class="bp-product-card__media"> <?php if($image_id): ?> <?php echo wp_get_attachment_image($image_id,'woocommerce_single',false,[ 'class'=>'bp-product-card__image', 'alt'=>$title, 'loading'=>'lazy', 'decoding'=>'async' ]); ?> <?php else: ?> <?php echo wp_kses_post(wc_placeholder_img('woocommerce_single',[ 'class'=>'bp-product-card__image' ])); ?> <?php endif; ?> </figure> <h3 class="bp-product-card__title"> <?php echo esc_html($title); ?> </h3> <?php if($category&&!is_wp_error($category_url)): ?> <a class="bp-product-card__category" href="<?php echo esc_url($category_url); ?>"> <?php echo esc_html($category->name); ?> </a> <?php endif; ?> <?php if($description!==''): ?> <p class="bp-product-card__description"> <?php echo esc_html($description); ?> </p> <?php endif; ?> <div class="bp-product-card__price"> <?php echo wp_kses_post($price); ?> </div> <div class="bp-product-card__action<?php echo $show_cart?'':' bp-product-card__action--single'; ?>"> <?php get_template_part('template-parts/components/buttons/button',null,[ 'label'=>'مشاهده محصول', 'mobile_label'=>'مشاهده', 'aria_label'=>'مشاهده محصول '.$title, 'url'=>$url, 'icon'=>'arrow-left', 'variant'=>'primary', 'class'=>'bp-product-card__view-button' ]); ?> <?php if($show_cart): ?> <form class="bp-product-card__cart-form" action="<?php echo esc_url($ajax_url); ?>" method="post"> <input type="hidden" name="product_id" value="<?php echo esc_attr($id); ?>"> <input type="hidden" name="quantity" value="1"> <button class="bp-product-card__cart-button" type="submit" aria-label="<?php echo esc_attr('افزودن '.$title.' به سبد خرید'); ?>" title="افزودن به سبد خرید"> <img src="<?php echo esc_url(get_theme_file_uri('assets/icons/cart.svg')); ?>" alt="" aria-hidden="true" width="18" height="18"> <svg class="bp-product-card__check" viewBox="0 0 24 24" width="20" height="20" fill="none" aria-hidden="true"> <path d="m5 12 4 4L19 6" stroke="currentColor" stroke-width="2.5" stroke-linecap="square" stroke-linejoin="miter"/> </svg> </button> </form> <?php endif; ?> </div> </article>